<script lang="ts">import PageShell from '$lib/components/PageShell.svelte';import {wallet} from '$lib/api';import type {Transaction} from '$lib/types';let balance=$state<number|null>(null),tx=$state<Transaction[]>([]);wallet.get().then(v=>balance=v.balanceSats).catch(()=>{});wallet.transactions().then(v=>tx=v).catch(()=>{})</script><PageShell eyebrow="WALLET" title="Your sats, in motion."><div class="wallet-hero"><span>AVAILABLE BALANCE</span><strong>{balance===null?'—':balance.toLocaleString()} sats</strong><div><button class="btn primary">Deposit</button><button class="btn ghost">Withdraw</button></div></div><div class="form-card"><p class="eyebrow">TRANSACTIONS</p>{#if !tx.length}<p class="state">No transactions yet.</p>{#each tx as t}<div class="tx"><span>{t.type}</span><strong>{t.amountSats} sats</strong></div>{/each}{/if}</div></PageShell>
